{"content": "{
  "main_characters": [
    {
      "name": "沈昭宁",
      "role": "protagonist",
      "identity": "省体操队运动员（重生前是国家队退役教练），24岁灵魂回到17岁身体，主项平衡木和自由操",
      "traits": ["责任感极强", "外冷内热", "行动派不善表达", "训练狂人", "对自己极度苛刻"],
      "overt_motivation": "弥补前世过失——拼命对纪霜晚好，保护她不再受伤，帮她拿到本该属于她的金牌",
      "covert_motivation": "渴望被原谅，更渴望重来一次能好好爱她——前世作为教练看着瘫痪的纪霜晚，那种无力感折磨了她整个后半生",
      "secret_fear": "害怕纪霜晚发现自己是重生的，更害怕自己的补偿反而再次伤害她",
      "misperception_of_other": "以为纪霜晚是普通少女，不知道对方也是重生者；以为自己的善意一定会被感知到",
      "hidden_connection": "前世最后十年一直以匿名身份资助纪霜晚的康复治疗费，纪霜晚不知道资助人是她"
    },
    {
      "name": "纪霜晚",
      "role": "deuteragonist",
      "identity": "省体操队运动员（重生前瘫痪退赛后成为体操评论员），23岁灵魂回到16岁身体，主项高低杠和平衡木",
      "traits": ["外柔内刚", "观察力极强", "隐忍克制", "表面温顺内心警觉", "极度缺乏安全感"],
      "overt_motivation": "复仇——回到过去亲眼盯住沈昭宁，搜集她'蓄意推人'的证据，在合适时机让她身败名裂",
      "covert_motivation": "内心深处渴望'那一推不是故意的'这个答案——她其实不想恨沈昭宁，因为前世在瘫痪前她们是最好的搭档，她爱过沈昭宁",
      "secret_fear": "害怕自己在这一世又沦陷于沈昭宁的温柔，害怕自己的记忆才是被扭曲的那个",
      "misperception_of_other": "坚信沈昭宁前世是蓄意推自己下平衡木（在她的记忆中，沈昭宁推人前的表情是冷漠的），将这一世沈昭宁的所有善举解读为'伪装'",
      "hidden_connection": "前世瘫痪后收到的匿名康复资助来自沈昭宁，但她一直以为是粉丝捐款"
    }
  ],
  "supporting_characters": [
    {
      "name": "程岚",
      "function": "助力",
      "identity": "省体操队主教练，两人的恩师",
      "description": "四十出头的女性，严厉但公正，眼光毒辣。前世在'平衡木事件'后愧疚自责（她负责器材检查但那天疏忽了），最终郁郁退休。这一世她是两个重生者都信任的第三方——掌握着当年器材故障的关键证据，但需要被触发才会回忆起来。她是解开误会的关键钥匙。"
    },
    {
      "name": "白芷",
      "function": "助力",
      "identity": "省体操队队友，自由操选手",
      "description": "开朗活泼的阳光少女，队里的气氛担当。和纪霜晚同寝室，无意中成为沈昭宁和纪霜晚之间的信息桥梁。直觉敏锐，最早察觉两人之间的异样氛围。后期成为两人感情的助攻手。"
    },
    {
      "name": "陆征",
      "function": "阻碍",
      "identity": "省体育局竞技处副处长",
      "description": "功利主义官僚，只看重金牌数据和政绩。在第二幕中成为外部压力来源——为争夺全运会名额，试图拆散沈昭宁和纪霜晚的双人搭档组合，要求她们各自为战以增加夺牌概率。是竞技线的主要阻碍。"
    },
    {
      "name": "江予安",
      "function": "反转点",
      "identity": "国家队体操选手，全国冠军",
      "description": "实力强劲的竞争对手，但并非反派。表面高冷实则尊重强者。她的存在是竞技线的标杆——沈昭宁和纪霜晚必须达到她的水平才能进国家队。后期与两人形成惺惺相惜的竞争关系，在决赛中是最大对手也是见证者。"
    },
    {
      "name": "何医生（何芸）",
      "function": "助力",
      "identity": "省队运动医学科主任",
      "description": "温和专业的队医，负责运动员伤病管理。在纪霜晚旧伤复发时提供关键医疗支持，同时在查阅旧病历时发现了前世'平衡木事件'中器材故障的医学佐证（伤口角度与'被推'不符），成为解开真相的辅助线索。"
    }
  ],
  "relationship_dynamics": "【核心关系】沈昭宁→纪霜晚：赎罪驱动的深爱，表现为过度保护和不求回报的付出，容易让对方感到窒息和怀疑。纪霜晚→沈昭宁：恐惧包裹下的未熄灭的爱，表现为高度警惕下不自觉的关注和心动，越靠近越害怕自己心软。\n\n【关系弧光】阶段一（第一幕）：试探与防备——沈拼命示好，纪全面戒备，两人在训练中不得不接触。阶段二（转折后）：误会解开后的尴尬期——纪为自己的恶意揣测愧疚，沈终于不用藏着掖着。阶段三（第二幕中后期）：联手训练中感情自然升温——从搭档到心动，竞技线和感情线双线推进。阶段四（第三幕）：面对外部压力和大赛考验，两人的感情经受最终考验，在赛场上实现双向奔赴。\n\n【配角关系网】程岚教练是两人共同信任的权威，白芷是情感催化剂和日常甜蜜的见证者，陆征是外部压力制造者，江予安是竞技标杆和最终对手，何医生是真相线的辅助推手。"
}", "path": "characters.json"}

{"content": "{
  "act_one": {
    "description": "第一幕·记忆的裂缝（第1-8章，约4万字，27%）：双重生开局，两人在省队重逢，沈昭宁拼命补偿、纪霜晚暗中戒备。通过训练中的接触、宿舍日常、队内选拔赛，两人的紧张关系逐步升级。在第7-8章，因平衡木训练事故再现，真相在程岚教练的器材检查记录中浮出水面——误会提前解开，但留下更深的情感课题：纪霜晚为自己的恶意愧疚，沈昭宁发现纪霜晚也是重生者。",
    "key_chapters": [
      {
        "chapter_number": 1,
        "chapter_title": "十七岁的镁粉",
        "core_event": "沈昭宁以教练身份死于车祸，在镁粉的气味中醒来——回到了17岁省队宿舍。今天是全省选拔赛前三个月，而纪霜晚就睡在她对面床铺。",
        "emotional_tone": "震惊→痛楚→坚定",
        "key_scenes": ["重生瞬间（车祸闪回→镁粉气味→睁眼看见省队宿舍天花板）", "第一次重新看见健全的纪霜晚——内心崩溃", "在训练馆里重新摸到平衡木时的手抖"]
      },
      {
        "chapter_number": 2,
        "chapter_title": "她的眼睛不对",
