        "emotional_tone": "甜蜜→日常→燃",
        "key_scenes": ["清晨训练：沈偷偷在纪的水壶上贴便签——被白芷发现", "沈用教练视角帮纪优化动作：'这个连接换成直体后空翻，分数多0.3'", "训练录像回放：纪的新编排流畅度惊人——程岚：'这是冠军级别。'", "晚上两人在宿舍走廊偷偷牵手——被查寝的程岚教练撞见，程岚假装没看到"]
      },
      {
        "chapter_number": 22,
        "chapter_title": "暴风前夜",
        "core_event": "全运会决赛前一周。陆征最后一次施压——他得到消息说沈和纪'关系过近影响训练'，威胁程岚：'如果她们的成绩不达标，两个人的名额都取消。'程岚力保两人。同时，江予安在社交媒体上发了一条训练视频——难度系数远超预期。纪和沈看完视频后，沈说：'怕吗？'纪说：'有你在，不怕。'",
        "emotional_tone": "紧张→坚定→温暖",
        "key_scenes": ["陆征最终施压——程岚背水一战力保两人", "江予安的训练视频：难度惊人", "赛前最后一次合练：沈和纪配合天衣无缝", "出发前夜：纪把头靠在沈肩上——'这一世，我们一起赢。'"]
      }
    ],
    "turning_point": "全运会决赛前夕，外部压力（陆征的拆档威胁+江予安的竞技压力）达到顶峰，两人的感情和竞技状态同时面临最终考验——是分开各自为战更安全，还是赌上一切并肩作战？她们选择了后者。"
  },
  "act_three": {
    "description": "第三幕·金色落地（第23-30章，约4万字，27%）：全运会决赛——沈昭宁和纪霜晚分别在个人全能、平衡木、高低杠等项目中与江予安和全国顶尖选手展开巅峰对决。竞技高潮、感情高潮、大圆满结局三线汇聚。",
    "key_chapters": [
      {
        "chapter_number": 23,
        "chapter_title": "全运会·开幕",
        "core_event": "全运会体操赛场。沈昭宁和纪霜晚以省队选手身份踏上全国最高竞技舞台。赛场氛围、对手云集、开幕式的震撼场面。两人在运动员通道里互相整理比赛服——沈帮纪别好发卡，纪帮沈系紧护腕。",
        "emotional_tone": "震撼→紧张→相互依靠",
        "key_scenes": ["全运会赛场全景——灯光、观众、裁判席", "运动员通道：两人互相整理装备的温柔细节", "与江予安在赛场相遇——点头致意，无声的竞争宣言", "程岚教练的赛前叮嘱：'享受比赛。'"]
      },
      {
        "chapter_number": 24,
        "chapter_title": "资格赛·破茧",
        "core_event": "资格赛。沈昭宁在跳马项目上完成了超高难度动作，排名第一进入决赛。纪霜晚在高低杠上发挥惊艳，仅次于江予安排名第二。两人都成功进入全能决赛圈。",
        "emotional_tone": "燃→专注→喜悦",
        "key_scenes": ["沈的跳马：前世教练的经验+这一世年轻的身体=完美发挥", "纪的高低杠：流畅如飞燕——全场最高执行分", "赛后两人在休息区碰拳：'决赛见。'"]
      },
      {
        "chapter_number": 25,
        "chapter_title": "决赛日·平衡木",
        "core_event": "平衡木决赛——这是两人的命运项目。沈昭宁第三个出场，完美发挥，暂列第一。纪霜晚倒数第二个出场，在做那个高难度后空翻连接时——她闭上了眼睛。因为她知道，就算平衡木只有10厘米宽，沈昭宁也会在下面接住她。完美落地。全场沸腾。",
        "emotional_tone": "极度紧张→燃到爆→热泪盈眶",
        "key_scenes": ["沈的平衡木表演：稳健完美——前世的遗憾在这一世弥补", "纪闭眼后空翻——回扣第17章的训练场景——完美落地", "分数出来：纪以0.05分优势超过沈——沈第一个冲上去抱她", "江予安在平衡木上失误——铜牌"]
      },
      {
        "chapter_number": 26,
        "chapter_title": "决赛日·全能之战",
        "core_event": "女子个人全能决赛。四个项目轮番上阵——跳马、高低杠、平衡木、自由操。沈和纪与江予安三人上演了三方拉锯战。最后一项自由操前，三人分差极小。沈昭宁的自由操以燃炸全场的编排拿下高分，纪霜晚紧随其后。最终：沈昭宁全能金牌，纪霜晚全能银牌，江予安铜牌。",
        "emotional_tone": "燃→拉锯→爆发→喜极而泣",
        "key_scenes": ["四项轮转的紧张拉锯——分数一直在三人间交替领先", "沈的自由操：前世教练生涯所有的积淀化为这一套动作", "纪的自由操：后空翻落地时的笑容——比任何金牌都珍贵", "最终排名公布：沈金纪银——两人在赛场上拥抱", "江予安走过来握手：'下次我不会输。'——惺惺相惜"]
      },
      {
        "chapter_number": 27,
        "chapter_title": "领奖台上的约定",
        "core_event": "颁奖典礼。沈昭宁站在最高领奖台上，纪霜晚在旁边——这是前世她们永远无法拥有的画面。国歌响起时，两人同时落泪。赛后新闻发布会上，记者问沈昭宁最想感谢谁，她看了纪一眼：'我的搭档。'",
        "emotional_tone": "圆满→感动→热泪",
        "key_scenes": ["领奖台：两人并排站着——回扣前世纪瘫痪在轮椅上看颁奖的记忆", "国歌响起：两人同时红了眼眶", "发布会：沈的回答让纪在台下咬住嘴唇忍住笑", "陆征在观众席——沉默了，最终鼓掌"]
      },
      {
        "chapter_number": 28,
        "chapter_title": "赛后·那些没说完的话",
        "core_event": "赛后回到省队。两人的关系在队内已经是公开的秘密。程岚教练找两人谈话——不是批评，而是以过来人的身份叮嘱：'竞技生涯很短，但你们的路还很长。'沈和纪开始规划未来——一起冲击亚运会、奥运会。纪霜晚正式放下了前世的记忆——不再是恨，也不再是愧疚，而是感恩。",
        "emotional_tone": "温暖→释然→展望未来",
        "key_scenes": ["程岚教练的谈话——她也释然了（前世的愧疚在这一世化解）", "纪在日记本上划掉了前世写的'证据清单'——写上新的一行：'这一世的证据：她爱我。'", "两人在训练馆里规划未来：'亚运会见？' '奥运会见。'"]
      },
      {
        "chapter_number": 29,
        "chapter_title": "旧螺栓与新起点",
        "core_event": "尾声前章。沈昭宁和纪霜晚一起回到省队器材室——找到了当年那批有问题的平衡木螺栓。沈把螺栓握在手心：'它改变了我们两辈子。'纪把手覆上去：'但这一世，它让我们在一起了。'两人一起把螺栓封进一个盒子里——象征着封存过去，迎接未来。",
        "emotional_tone": "感慨→释然→坚定",
        "key_scenes": ["器材室：找到旧螺栓——沈的手在抖", "纪握住沈的手：'它改变了两辈子，但这一世是好的改变。'", "封存螺栓——白芷帮忙找了一个漂亮的木盒子", "何医生路过：'你们在搞什么仪式？' 白芷：'成人礼！'"]
      },
      {
        "chapter_number": 30,
        "chapter_title": "十厘米的世界",
        "core_event": "大结局。时间线推进到一年后——沈昭宁和纪霜晚入选国家队，备战亚运会。最后一个场景：清晨的国家队训练馆，纪霜晚站在平衡木上热身。沈昭宁推门进来，站在平衡木下仰头看她——和前世完全相反的画面。纪从平衡木上跳下来，稳稳落在沈面前。沈伸手接住她。'又是新的一天。' '又是新的一天。'",
        "emotional_tone": "温暖→圆满→余韵悠长",
        "key_scenes": ["一年后的国家队训练馆——两人的新日常", "平衡木上的镜像场景：与前世形成完美对照", "纪从平衡木上跳下——沈接住——与第7章的飞扑接人形成回扣", "最后一句对话：'又是新的一天。'", "结尾彩蛋：白芷在国家队群里发了一张偷拍——沈帮纪系鞋带——配文'全国冠军也要有人系鞋带哦'"]
      }
    ],
    "turning_point": "全运会金牌+关系圆满确认——两人从前世的遗憾走向这一世的圆满，在竞技场上并肩登顶，在生活中携手同行。平衡木从'命运的诅咒'变成'爱情的见证'。"
  }
}", "path": "outline.json"}

environment.content:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "characters.schema.json",
  "title": "小说人物设计",
  "description": "人物一致性的参考依据，避免角色崩坏",
  "type": "object",
  "required": ["main_characters"],
  "properties": {
    "main_characters": {
      "type": "array",
      "description": "主角/核心角色数组",
      "minItems": 1,
      "items": {
        "type": "object",
        "required": [
          "name",
          "role",
          "traits",
          "overt_motivation",
          "covert_motivation",
          "secret_fear"
        ],
        "properties": {
          "name": {
            "type": "string",
            "description": "角色姓名"
          },
          "role": {
            "type": "string",
            "enum": ["protagonist", "deuteragonist"],
            "description": "角色类型：protagonist=第一主角，deuteragonist=第二主角"
          },
          "identity": {
            "type": "string",
            "description": "身份职业/社会角色"
          },
          "traits": {
            "type": "array",
            "description": "核心性格特质关键词（3-5个）",
            "items": {
              "type": "string"
            },
            "minItems": 3,
            "maxItems": 5
          },
          "overt_motivation": {
            "type": "string",
            "description": "显性动机（表面目标）"
          },
          "covert_motivation": {
            "type": "string",
            "description": "隐性动机（深层需求）"
          },
          "secret_fear": {
            "type": "string",
            "description": "秘密恐惧（内心脆弱点）"
          },
          "misperception_of_other": {
            "type": "string",
            "description": "对其他主角的错位认知"
          },
          "hidden_connection": {
            "type": "string",
            "description": "与其他角色的隐藏连接"
          }
        }
      }
    },
    "supporting_characters": {
      "type": "array",
      "description": "配角/次要角色数组",
      "items": {
        "type": "object",
        "required": ["name", "function"],
        "properties": {
          "name": {
            "type": "string",
            "description": "配角姓名"
          },
          "function": {
            "type": "string",
            "enum": ["助力", "阻碍", "反转点"],
            "description": "对主角的作用类型"
          },
          "identity": {
            "type": "string",
            "description": "配角身份"
          },
          "description": {
            "type": "string",
            "description": "配角简要描述"
          }
        }
      }
    },
    "relationship_dynamics": {
      "type": "string",
      "description": "角色关系动态描述"
    }
  }
}

{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "creative_intent.schema.json",
  "title": "小说创作意图配方",
  "description": "记录用户需求理解和配方选择结果，作为创作的北极星",
  "type": "object",
  "required": ["user_need", "inspiration_state", "extracted_elements", "selected_recipe", "one_sentence_synopsis"],
  "properties": {
    "user_need": {
      "type": "string",
      "description": "用户的原始输入文本",
      "minLength": 1
    },
    "inspiration_state": {
      "type": "string",
      "enum": ["no_inspiration", "vague_inspiration", "clear_inspiration"],
      "description": "用户创作时的灵感清晰程度"
    },
    "extracted_elements": {
      "type": "object",
      "description": "从用户输入中提取的创作关键要素",
      "required": ["emotion_verbs", "scene_elements", "relationship_tension"],
      "properties": {
        "emotion_verbs": {
          "type": "array",
          "description": "情感动词/核心动作（决定X轴剧情模式）",
          "items": {
            "type": "string"
          },
          "minItems": 1
        },
        "scene_elements": {
          "type": "array",
          "description": "场景要素/世界观元素（决定Y轴标签）",
          "items": {
            "type": "string"
          },
          "minItems": 1
        },
        "relationship_tension": {
          "type": "array",
          "description": "人物关系张力/冲突来源",
          "items": {
            "type": "string"
          },
          "minItems": 1
        },
        "user_preferences": {
          "type": "object",
          "description": "用户的情感偏好和禁忌",
          "properties": {
            "desired_emotion": {
              "type": "string",
              "description": "期望的情感倾向"
            },
            "forbidden": {
              "type": "array",
              "description": "明确拒绝的元素",
              "items": {
                "type": "string"
              }
            }
          }
        }
      }
    },
    "selected_recipe": {
      "type": "object",
      "description": "用户选定的创作配方（X-Y轴化学反应组合）",
      "required": [
        "x_axis_mode_id",
        "x_axis_mode_name",
        "y_axis_tags",
        "reaction_strength",
        "tension_stars",
        "forbidden_elements"
      ],
      "properties": {
        "x_axis_mode_id": {
          "type": "string",
          "pattern": "^[A-G]\\d{1,2}$",
          "enum": [
            "A1", "A2", "A3", "A4", "A5", "A6",
            "B7", "B8", "B9", "B10", "B11", "B12",
            "C13", "C14", "C15", "C16", "C17", "C18",
            "D19", "D20", "D21", "D22", "D23",
            "E24", "E25", "E26", "E27", "E28",
            "F29", "F30", "F31", "F32", "F33", "F34",
            "G35", "G36"
          ],
          "description": "普罗蒂36种剧情模式的标识符"
        },
        "x_axis_mode_name": {
          "type": "string",
          "description": "X轴模式的中文名称"
        },
        "y_axis_tags": {
          "type": "array",
          "description": "现代网文核心标签（表达载体）",
          "items": {
            "type": "string",
            "enum": [
              "双向暗恋",
              "系统流",
              "无限流",
              "种田流",
              "赛博朋克",
              "规则怪谈",
              "重生/穿越",
              "商战权谋",
              "克苏鲁",
              "第四天灾",
              "仙侠修真",
              "刑侦悬疑"
            ]
          },
          "minItems": 2,
          "maxItems": 3
        },
        "reaction_strength": {
          "type": "string",
          "enum": ["↗", "↘", "✷"],
          "description": "X轴与Y轴的化学反应强度符号"
        },
        "tension_stars": {
          "type": "integer",
          "minimum": 1,
          "maximum": 5,
          "description": "故事张力指数（1-5星）"
        },
        "forbidden_elements": {
          "type": "array",
          "description": "避雷红线（创作禁忌元素）",
          "items": {
            "type": "string"
          },
          "minItems": 1
        },
        "x_axis_display": {
          "type": "string",
          "description": "X轴模式在故事中的具体显影方式"
        },
        "y_axis_combination_effect": {
          "type": "string",
          "description": "Y轴标签组合产生的效应描述"
        },
        "reaction_formula": {
          "type": "string",
          "description": "化学反应公式的一句话描述"
        },
        "platform_fit": {
          "type": "array",
          "description": "适合发布的平台类型",
          "items": {
            "type": "string"
          }
        }
      }
    },
    "one_sentence_synopsis": {
      "type": "string",
      "description": "一句话故事梗概（30-50字）",
      "minLength": 30,
      "maxLength": 50
    }
  }
}

{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "outline.schema.json",
  "title": "小说故事大纲",
  "description": "节奏规划参考，确保故事有合理的起承转合",
  "type": "object",
  "required": ["act_one", "act_two", "act_three"],
  "properties": {
    "act_one": {
      "type": "object",
      "description": "第一幕：开篇（20-30%篇幅）- 建立世界观、引入主角和核心冲突",
      "required": ["description", "key_chapters", "turning_point"],
      "properties": {
        "description": {
          "type": "string",
          "description": "该幕的核心任务描述"
        },
        "key_chapters": {
          "type": "array",
          "description": "该幕的关键章节数组",
          "minItems": 1,
          "items": {
            "type": "object",
            "required": ["chapter_number", "chapter_title", "core_event"],
            "properties": {
              "chapter_number": {
                "type": "integer",
                "minimum": 1,
                "description": "章节编号"
              },
              "chapter_title": {
                "type": "string",
                "description": "章节标题"
              },
              "core_event": {
                "type": "string",
                "description": "本章核心事件（1-2句话）"
              },
              "emotional_tone": {
                "type": "string",
                "description": "本章情感基调"
              },
              "key_scenes": {
                "type": "array",
                "description": "本章关键场景列表",
                "items": {
                  "type": "string"
                }
              }
            }
          }
        },
        "turning_point": {
          "type": "string",
          "description": "本幕结尾的转折点"
        }
      }
    },
    "act_two": {
      "type": "object",
      "description": "第二幕：挣扎（40-50%篇幅）- 冲突升级、主角陷入困境",
      "required": ["description", "key_chapters", "turning_point"],
      "properties": {
        "description": {
          "type": "string",
          "description": "该幕的核心任务描述"
        },
        "key_chapters": {
          "type": "array",
          "description": "该幕的关键章节数组",
          "minItems": 1,
          "items": {
            "type": "object",
            "required": ["chapter_number", "chapter_title", "core_event"],
            "properties": {
              "chapter_number": {
                "type": "integer",
                "minimum": 1,
                "description": "章节编号"
              },
              "chapter_title": {
                "type": "string",
                "description": "章节标题"
              },
